#include <stdio.h>
#include <string.h>

int main() {
    char s[100005];
    if (fgets(s, sizeof(s), stdin) == NULL) return 0;
    int len = strlen(s);
    while (len > 0 && (s[len-1] == '\n' || s[len-1] == '\r')) {
        len--;
    }
    for (int i = len - 1; i >= 0; i--) {
        putchar(s[i]);
    }
    putchar('\n');
    return 0;
}
